<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {createClient} from '../lib/client';
import {sizeText,speedText,timeText,stateText} from '../lib/model';
import PolicyEditor from './PolicyEditor.vue';
import '../styles.css';
const props=defineProps({api:{type:Object,default:()=>({})},pluginId:{type:String,default:'FlowBrush'},sourcePluginId:String});
const emit=defineEmits(['close','switch','layout']);
const client=createClient(props.api,props.pluginId),data=ref(null),error=ref(''),loading=ref(true),refreshing=ref(false),tab=ref('overview'),config=ref({}),saving=ref(false),submitting=ref(false),siteEdit=ref(false),allSites=ref(false),toast=ref(''),query=ref(''),filter=ref('all'),historyMode=ref('live'),page=ref(1),expanded=ref(null);
let timer,sequence=0,destroyed=false;
const summary=computed(()=>data.value?.summary||{}),policy=computed(()=>data.value?.policy||{}),job=computed(()=>data.value?.job||{});
const running=computed(()=>job.value.status==='running');
const sites=computed(()=>[...(data.value?.sites||[])].sort((a,b)=>Number(b.enabled)-Number(a.enabled)||(b.downloading||0)-(a.downloading||0)||a.name.localeCompare(b.name,'zh-CN')));
const visibleSites=computed(()=>sites.value.filter(s=>s.enabled||s.downloading||s.seeding));
const filtered=computed(()=>{
 const rows=historyMode.value==='live'?data.value?.tasks||[]:data.value?.history||[];
 return rows.filter(t=>(filter.value==='all'||t.status===filter.value)&&(t.title+' '+t.site).toLowerCase().includes(query.value.toLowerCase()));
});
const paged=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12));
async function load(initial=false){
 const seq=++sequence;refreshing.value=true;
 try{const d=await client.workspace();if(destroyed||seq!==sequence)return;data.value=d;error.value='';if(initial)config.value=await client.config();}
 catch(e){if(!destroyed&&seq===sequence)error.value=e.message||'读取工作台失败';}
 finally{if(!destroyed&&seq===sequence){loading.value=false;refreshing.value=false;}}
}
async function changeTab(value){tab.value=value;error.value='';if(value==='strategy'){try{config.value=await client.config();}catch(e){error.value=e.message;}}}
async function editSites(){try{config.value=await client.config();siteEdit.value=true;}catch(e){error.value=e.message;}}
async function save(changes){saving.value=true;error.value='';try{await client.save(changes);config.value=await client.config();siteEdit.value=false;toast.value='策略已保存并生效';await load();}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function run(){submitting.value=true;try{await client.run();toast.value='已开始选种，运行结果会自动更新';await load();}catch(e){error.value=e.message;}finally{submitting.value=false;}}
function resetFilter(){page.value=1;}
function metric(v){return v==null?'—':v;}
onMounted(async()=>{emit('layout',{maxWidth:'86rem'});await load(true);timer=setInterval(()=>{if(!document.hidden&&!refreshing.value)load();},15000);});
onBeforeUnmount(()=>{destroyed=true;clearInterval(timer);sequence++;});
</script>
<template>
<div class="fb-root">
 <header class="fb-header"><div class="fb-brand"><div class="fb-brandmark"><v-icon icon="mdi-chart-timeline-variant-shimmer" size="30"/></div><div><div class="fb-kicker">FLOWBRUSH <span>· v{{data?.version||'4.5'}}</span></div><h1>刷流工作台</h1><p>把下载名额留给有需求的种子。</p></div></div><div class="fb-header-actions"><span class="fb-pill" :class="data?.enabled?'green':''"><i/>{{data?.enabled?'自动运行中':'自动运行已关闭'}}</span><v-btn variant="outlined" icon="mdi-refresh" aria-label="刷新工作台" :loading="refreshing" @click="load()"/><v-btn color="primary" prepend-icon="mdi-play" :loading="submitting||running" :disabled="!data" @click="run">运行一轮</v-btn></div></header>
 <nav class="fb-tabs" aria-label="刷流工作台导航"><button v-for="item in [{id:'overview',name:'运行概况',icon:'mdi-view-dashboard-outline'},{id:'strategy',name:'选种策略',icon:'mdi-tune-variant'},{id:'sites',name:'站点分配',icon:'mdi-domain'},{id:'history',name:'任务记录',icon:'mdi-format-list-bulleted'}]" :key="item.id" :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="changeTab(item.id)"><v-icon :icon="item.icon" size="19"/>{{item.name}}</button></nav>
 <v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{error}}<v-btn variant="text" @click="load()">重试</v-btn></v-alert>
 <v-alert v-if="data?.live_error" type="warning" variant="tonal" class="mb-5">{{data.live_error}}。统计未按零处理。</v-alert>
 <div v-if="loading" class="fb-loading"><v-progress-circular indeterminate color="primary"/><p>正在读取下载器与站点状态</p></div>
 <template v-else-if="data">
  <template v-if="tab==='overview'">
   <div class="fb-metrics"><article class="fb-metric featured"><span><v-icon icon="mdi-arrow-up" size="18"/>实时上传</span><strong>{{speedText(summary.upload_speed)}}</strong><small>当前刷流任务累计上传 {{sizeText(summary.uploaded)}}</small></article><article class="fb-metric"><span><v-icon icon="mdi-arrow-down" size="18"/>实时下载</span><strong>{{speedText(summary.download_speed)}}</strong><small>{{data.downloader||'未选择下载器'}}</small></article><article class="fb-metric"><span><v-icon icon="mdi-layers-outline" size="18"/>下载名额</span><strong>{{metric(summary.downloading)}}<em>/ {{policy.max_downloads||'不限'}}</em></strong><small>包含未完成的等待与暂停任务</small></article><article class="fb-metric"><span><v-icon icon="mdi-seed-outline" size="18"/>持续做种</span><strong>{{metric(summary.seeding)}}<em>个</em></strong><small>当前任务体积 {{sizeText(summary.size)}}</small></article></div>
   <div class="fb-overview-grid"><section class="fb-panel"><div class="fb-section-title"><div><span class="fb-eyebrow">资源分配</span><h2>各站的下载名额</h2><p>每站最多 {{policy.site_cap||'不限'}} 个，每轮新增 {{policy.cycle_cap||'不限'}} 个。</p></div><v-btn variant="text" color="primary" @click="changeTab('sites')">查看全部<v-icon icon="mdi-arrow-right" size="18"/></v-btn></div>
    <div v-if="visibleSites.length" class="fb-allocation"><div v-for="site in visibleSites" :key="site.id" class="fb-allocation-row"><div><span class="fb-site-dot">{{site.name.slice(0,1)}}</span><div><strong>{{site.name}}</strong><small>{{site.reason}}</small></div></div><div class="fb-quota"><div class="fb-meter"><i :style="{width:site.downloading==null?'0%':Math.min(100,(site.downloading/(site.cap||policy.site_cap||1))*100)+'%'}"/></div><span>{{metric(site.downloading)}} / {{site.cap||'∞'}}</span></div></div></div><p v-else class="fb-empty">尚未选择站点。<button class="fb-link" @click="editSites">选择刷流站点</button></p>
   </section><aside class="fb-panel fb-run"><span class="fb-eyebrow">最近一轮</span><div class="fb-run-icon" :class="job.status==='error'?'bad':''"><v-icon :icon="running?'mdi-progress-clock':job.status==='error'?'mdi-alert-circle-outline':'mdi-check-circle-outline'" size="34"/></div><h2>{{running?'正在选种':job.message||'等待首次运行'}}</h2><p>{{job.started_at?timeText(job.started_at):'运行后可查看每个站点的筛选结果。'}}</p><div class="fb-run-facts"><span>新增任务<strong>{{job.added??'—'}} 个</strong></span><span>本轮检查站点<strong>{{Object.keys(job.sites||{}).length}} 站</strong></span><span>自动选种<strong>{{data.enabled?'已开启':'已关闭'}}</strong></span></div><v-btn variant="outlined" block @click="changeTab('sites')">查看筛选结果</v-btn></aside></div>
   <section class="fb-policy-strip"><div><v-icon icon="mdi-filter-variant"/><strong>当前选种策略</strong></div><span>{{policy.size||'不限'}} GiB</span><span>{{policy.pubtime?'近 '+Number(String(policy.pubtime).split('-').at(-1))/60+' 小时':'不限发布时间'}}</span><span>下载者 ≥ {{policy.min_peers||0}}</span><span>{{policy.freeleech?'仅免费':'不限促销'}}</span><span>{{policy.demand_priority?'需求优先':'新种优先'}}</span><button class="fb-link" @click="changeTab('strategy')">调整策略</button></section>
  </template>
  <template v-if="tab==='strategy'"><div class="fb-page-title"><div><h2>选种策略</h2><p>筛选与容量集中管理，分站保种规则独立生效。</p></div></div><PolicyEditor :initial="config" :sites="sites" :downloaders="data.downloaders" section="strategy" :saving="saving" @save="save" @cancel="changeTab('overview')"/></template>
  <template v-if="tab==='sites'"><div class="fb-page-title"><div><h2>站点分配</h2><p>{{sites.filter(s=>s.enabled).length}} 个站点允许新增 · 已停用站点的历史任务继续维护</p></div><v-btn color="primary" variant="tonal" prepend-icon="mdi-pencil-outline" @click="editSites">编辑站点范围</v-btn></div><div class="fb-site-filter"><v-btn variant="text" size="small" @click="allSites=!allSites">{{allSites?'只看已启用及有任务的站点':'显示全部 '+sites.length+' 个站点'}}</v-btn></div><div class="fb-site-grid"><article v-for="site in (allSites?sites:visibleSites)" :key="site.id" class="fb-panel fb-site-card" :class="{muted:!site.enabled&&!site.downloading&&!site.seeding}"><header><div><span class="fb-site-dot">{{site.name.slice(0,1)}}</span><h3>{{site.name}}</h3></div><span class="fb-pill" :class="site.enabled?'green':''">{{site.enabled?'允许新增':'停止新增'}}</span></header><p class="fb-site-reason">{{site.reason}}</p><div class="fb-site-stats"><span>下载<strong>{{metric(site.downloading)}}<small> / {{site.cap||'∞'}}</small></strong></span><span>做种<strong>{{metric(site.seeding)}}</strong></span><span>上传<strong>{{speedText(site.upload_speed)}}</strong></span></div><div class="fb-retention"><v-icon icon="mdi-shield-check-outline" size="17"/><span>{{site.policy.hr?'H&R 站点 · ':''}}{{site.policy.seed_hours?'完整下载后做种 '+site.policy.seed_hours+' 小时':'保留现有任务'}}</span></div><div v-if="site.last_result.message" class="fb-site-result"><strong>最近一轮</strong><p>{{site.last_result.message}}</p><button v-if="Object.keys(site.last_result.rejected||{}).length" class="fb-link" :aria-expanded="expanded===site.id" @click="expanded=expanded===site.id?null:site.id">{{expanded===site.id?'收起':'查看'}}筛选原因</button><ul v-if="expanded===site.id"><li v-for="(count,reason) in site.last_result.rejected" :key="reason"><span>{{reason}}</span><b>{{count}}</b></li></ul></div></article></div></template>
  <template v-if="tab==='history'"><div class="fb-page-title"><div><h2>任务记录</h2><p>{{historyMode==='live'?'下载器实时状态，15 秒自动刷新':'最近 200 条刷流记录；删除标记以插件检查结果为准'}}</p></div><v-btn-toggle v-model="historyMode" mandatory density="comfortable" color="primary" @update:model-value="filter='all';resetFilter()"><v-btn value="live">当前任务</v-btn><v-btn value="history">历史记录</v-btn></v-btn-toggle></div><div class="fb-table-tools"><v-text-field v-model="query" label="搜索任务或站点" prepend-inner-icon="mdi-magnify" variant="outlined" density="compact" hide-details @update:model-value="resetFilter"/><v-select v-if="historyMode==='live'" v-model="filter" label="状态" :items="[{title:'全部状态',value:'all'},...['downloading','waiting','seeding','paused','error'].map(s=>({title:stateText(s),value:s}))]" variant="outlined" density="compact" hide-details @update:model-value="resetFilter"/></div><div class="fb-panel fb-task-list"><div v-for="(task,index) in paged" :key="task.hash||index" class="fb-task"><div class="fb-task-main"><span class="fb-site-label">{{task.site}}</span><h3>{{task.title}}</h3><div class="fb-task-meta"><span>{{sizeText(task.size)}}</span><span>{{timeText(task.added_on)}}</span><span class="fb-status" :class="task.status">{{historyMode==='live'?stateText(task.status):(task.deleted?'已删除':'记录保留')}}</span></div><div v-if="historyMode==='live'" class="fb-progress"><i :style="{width:(task.progress*100)+'%'}"/></div></div><div class="fb-task-traffic"><strong v-if="historyMode==='live'">{{(task.progress*100).toFixed(1)}}%</strong><span>↑ {{historyMode==='live'?speedText(task.upload_speed):sizeText(task.uploaded)}}</span><span>↓ {{historyMode==='live'?speedText(task.download_speed):sizeText(task.downloaded)}}</span></div></div><div v-if="!paged.length" class="fb-empty"><v-icon icon="mdi-text-box-search-outline" size="34"/><h3>{{data.live_error&&historyMode==='live'?'暂时无法读取任务':'没有匹配的任务'}}</h3><p>可调整搜索或切换记录范围。</p></div></div><div class="fb-pagination"><span>共 {{filtered.length}} 条</span><v-pagination v-model="page" :length="Math.max(1,Math.ceil(filtered.length/12))" :total-visible="4" density="comfortable"/></div></template>
  <footer class="fb-footer"><span>刷流 v{{data.version}} · {{data.downloader}}</span><span>最近刷新 {{timeText(data.checked_at)}} · 上传收益以站点统计为准</span></footer>
 </template>
 <v-dialog v-model="siteEdit" max-width="850" scrollable><v-card class="fb-root fb-dialog"><v-card-title class="fb-dialog-title">站点范围<v-btn icon="mdi-close" aria-label="关闭站点范围" variant="text" @click="siteEdit=false"/></v-card-title><v-card-text><v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert><PolicyEditor :initial="config" :sites="sites" :downloaders="data?.downloaders||[]" section="sites" :saving="saving" @save="save" @cancel="siteEdit=false"/></v-card-text></v-card></v-dialog>
 <v-snackbar :model-value="!!toast" @update:model-value="v=>{if(!v)toast=''}" :timeout="4000">{{toast}}</v-snackbar>
</div>
</template>
